// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetActivity Recent node activity (downloads, loads, evictions, declines)
	// (GET /api/v1/activity)
	GetActivity(w http.ResponseWriter, r *http.Request)
	// GetCatalog Model catalog merged with local state
	// (GET /api/v1/catalog)
	GetCatalog(w http.ResponseWriter, r *http.Request, params GetCatalogParams)
	// GetEarnings Earnings (ledger-backed when enrolled, else a labelled estimate)
	// (GET /api/v1/earnings)
	GetEarnings(w http.ResponseWriter, r *http.Request)
	// EnrollNode Enroll (or re-enroll) this node with the coordinator
	// (POST /api/v1/enroll)
	EnrollNode(w http.ResponseWriter, r *http.Request)
	// GetHealth Liveness probe
	// (GET /api/v1/health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetLimits Live governor limits
	// (GET /api/v1/limits)
	GetLimits(w http.ResponseWriter, r *http.Request)
	// UpdateLimits Update governor limits
	// (PUT /api/v1/limits)
	UpdateLimits(w http.ResponseWriter, r *http.Request)
	// GetLogs Recent daemon log entries (ring buffer)
	// (GET /api/v1/logs)
	GetLogs(w http.ResponseWriter, r *http.Request, params GetLogsParams)
	// ListModels Locally installed models
	// (GET /api/v1/models)
	ListModels(w http.ResponseWriter, r *http.Request)
	// DeleteModel Delete a model from disk (and unload it if loaded)
	// (DELETE /api/v1/models/{id})
	DeleteModel(w http.ResponseWriter, r *http.Request, id ModelID)
	// SetDefaultModel Serve this model when a request names none (must be loaded)
	// (POST /api/v1/models/{id}/default)
	SetDefaultModel(w http.ResponseWriter, r *http.Request, id ModelID)
	// CancelModelDownload Cancel an in-flight download (the .partial file is kept for resume)
	// (DELETE /api/v1/models/{id}/download)
	CancelModelDownload(w http.ResponseWriter, r *http.Request, id ModelID)
	// StartModelDownload Start downloading a catalog model in the background
	// (POST /api/v1/models/{id}/download)
	StartModelDownload(w http.ResponseWriter, r *http.Request, id ModelID)
	// LoadModel Load a model into the serving runtime
	// (POST /api/v1/models/{id}/load)
	LoadModel(w http.ResponseWriter, r *http.Request, id ModelID)
	// PinModel Pin or unpin a model (pinned models are never LRU-evicted)
	// (POST /api/v1/models/{id}/pin)
	PinModel(w http.ResponseWriter, r *http.Request, id ModelID)
	// UnloadModel Unload a model from the runtime (the artifact stays cached)
	// (POST /api/v1/models/{id}/unload)
	UnloadModel(w http.ResponseWriter, r *http.Request, id ModelID)
	// GetRequests What the node is doing right now, and what it did recently
	// (GET /api/v1/requests)
	GetRequests(w http.ResponseWriter, r *http.Request, params GetRequestsParams)
	// GetStatus Node status snapshot
	// (GET /api/v1/status)
	GetStatus(w http.ResponseWriter, r *http.Request)
	// CheckUpdate Run a version check now
	// (POST /api/v1/update/check)
	CheckUpdate(w http.ResponseWriter, r *http.Request)
}

